    },
    {
      "card_ids": ["C07"],
      "claim": "In humans, the PET ligand 11C-AZD2184 crossed the blood-brain barrier and reached peak brain concentration after intravenous injection, demonstrating CNS access after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct in vivo records with high assay-transfer scores demonstrate BBB penetration and brain uptake after systemic administration, supporting meaningful CNS access. No evidence argues against brain penetration.",
  "evidence_gaps": [
    "No direct experimental record was provided under the specific brain tumor or glioma condition; evidence comes from non-tumor in vivo models.",
    "No tumor-specific brain uptake or unbound brain exposure data were reported."
  ],
